def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()
        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"
        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return (
            bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def normalize_phone(value):
        marker = re.search(r"(?:ext|x|#)", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        return digits

    def valid_phone(value):
        return len(value) == 10 and value[0] not in {"0", "1"}

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    def normalize_tags(value):
        return {
            tag.strip().lower()
            for tag in re.split(r"[;,]", value)
            if tag.strip()
        }

    prepared = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        email_is_valid = valid_email(email)
        phone_is_valid = valid_phone(phone)

        # Rows without either usable identifier cannot participate in matching.
        if not email_is_valid and not phone_is_valid:
            continue

        prepared.append({
            "input_index": input_index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email if email_is_valid else "",
            "phone": phone if phone_is_valid else "",
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": normalize_tags(row["tags"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "updated": parse_updated(row["updated"]),
        })

    # Disjoint-set union handles transitive matches.
    parent = list(range(len(prepared)))
    rank = [0] * len(prepared)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a = find(a)
        root_b = find(b)
        if root_a == root_b:
            return
        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a
        parent[root_b] = root_a
        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1

    email_owner = {}
    phone_last_owner = {}

    for i, row in enumerate(prepared):
        if row["email"]:
            if row["email"] in email_owner:
                union(i, email_owner[row["email"]])
            else:
                email_owner[row["email"]] = i

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            if key in phone_last_owner:
                union(i, phone_last_owner[key])
            else:
                phone_last_owner[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    def choose_field(group, field):
        candidates = [row for row in group if row[field] != ""]
        if not candidates:
            return ""
        best = min(
            candidates,
            key=lambda row: (
                0 if row["source"].casefold() == "manual" else 1,
                -row["updated"].timestamp(),
                row["input_index"],
            ),
        )
        return best[field]

    output = []

    for group in groups.values():
        latest = max(row["updated"] for row in group)
        tags = sorted(set().union(*(row["tags"] for row in group)))

        output.append({
            "first_name": choose_field(group, "first_name"),
            "last_name": choose_field(group, "last_name"),
            "zip": choose_field(group, "zip"),
            "email": choose_field(group, "email"),
            "phone": choose_field(group, "phone"),
            "source": choose_field(group, "source"),
            "tags": ";".join(tags),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
            "_earliest_index": min(row["input_index"] for row in group),
        })

    output.sort(key=lambda person: person["_earliest_index"])
    for person in output:
        del person["_earliest_index"]

    return output
